/* --- Changelog --------------------------------------------------------- */

export interface Release {
  version: string;
  date: string;
  status: T;
  notes: T[];
}

export const RELEASES: Release[] = [
  {
    version: '1.0',
    date: '2026-08-12',
    status: { en: 'Proposal — Review Board forming', es: 'Propuesta — Review Board en formación' },
    notes: [
      { en: 'First publication: twenty-seven normative clauses, the nine-property test, the WRM framework, the 120-principle matrix, the maturity model, the HWFA instrument, the Hybrid Workforce Manager role and the transition playbooks.', es: 'Primera publicación: veintisiete cláusulas normativas, el test de nueve propiedades, el marco WRM, la matriz de 120 principios, el modelo de madurez, el instrumento HWFA, el rol de Gerente de Fuerza Laboral Híbrida y los playbooks de transición.' },
      { en: 'Certification was deliberately excluded from scope. This standard scores no products and issues no seals.', es: 'La certificación se excluyó deliberadamente del alcance. Este estándar no puntúa productos ni emite sellos.' },
      { en: 'The HWFS returns a structured argument rather than a 0–100 score, resolving a contradiction present in the source research.', es: 'El HWFS devuelve un argumento estructurado en lugar de un puntaje 0–100, resolviendo una contradicción presente en la investigación de origen.' },
      { en: 'HWF-17, HWF-18 and HWF-19 were corrected together. HWF-17 no longer trusts the resource to detect its own divergence: a system whose model or configuration is the problem shares the blind spot, so independent monitoring against the contract is now the primary control and the self-report a supplementary signal. HWF-18’s vocabulary was operationalised — restrictions prevent measurable degradation of the decision (anchoring, contamination, saturation) rather than protect “the resource’s judgement” — and G-31 was renamed from deliberate opacity, which read as legitimised opacity and quoted badly out of context, to context boundary record, naming the artifact as the glossary’s other instrument terms do. HWF-19’s note dropped the claim that pointless human posts prune themselves — empirically false, bureaucracies carry dead posts for decades — for the stronger and honest version: human pruning triggers are weak and fail often, and an artificial post removes even those, losing the last occasions on which anyone would notice it. And a lapsed review no longer reads as automatic retirement: it escalates and restricts or suspends in proportion while the review is forced — retirement is the outcome of a failed justification, never of a missed calendar, matching the lifecycle’s Suspend-before-Retire order. No counts changed.', es: 'HWF-17, HWF-18 y HWF-19 se corrigieron juntas. HWF-17 ya no confía en que el recurso detecte su propia divergencia: un sistema cuyo modelo o configuración son el problema comparte el punto ciego, así que el monitoreo independiente contra el contrato es ahora el control primario y el auto-reporte una señal complementaria. El vocabulario de HWF-18 se operacionalizó — las restricciones previenen la degradación medible de la decisión (anclaje, contaminación, saturación) en vez de proteger «el criterio del recurso» — y G-31 se renombró de opacidad deliberada, que se leía como opacidad legitimada y citaba mal fuera de contexto, a registro de frontera de contexto, nombrando el artefacto como lo hacen los demás términos de instrumento del glosario. La nota de HWF-19 abandonó la afirmación de que los puestos humanos sin sentido se podan solos — empíricamente falsa, las burocracias cargan puestos muertos por décadas — por la versión más fuerte y honesta: los disparadores humanos de poda son débiles y fallan seguido, y un puesto artificial elimina hasta esos, perdiendo las últimas ocasiones en que alguien lo notaría. Y una revisión vencida ya no se lee como retiro automático: escala y restringe o suspende en proporción mientras se fuerza la revisión — el retiro es el resultado de una justificación fallida, nunca de un calendario perdido, calzando con el orden Suspender-antes-de-Retirar del lifecycle. Ningún conteo cambió.' },
      { en: 'The Fit Score became the Fit Assessment — HWFA — and was rebuilt in three stages. The rename first: an instrument that deliberately refuses to produce a number should not be called a Score, and retiring the old acronym also dissolves any residual confusion between the instrument and the standard. The redesign fixes three defects a review caught against the running code: the economics dimension was circular — it asked which alternative wins and returned the answer as analysis — and is now a factual cost profile consulted only in the final stage; full enumerability scored toward probabilistic AI when it is the signature of deterministic-software territory, and the instrument now has a fourth outcome — deterministic automation — for rule-following work with a thin exception tail, because a standard about AI Employees whose instrument can say “you do not need one” is harder to dismiss as hype; and volume pulled toward automation when scale multiplies harm, so it now amplifies the risk class instead. The stages embody HWF-20’s order — eligibility, then risk, then economics — opening with a new reserved-subjects dimension wired to HWF-23, and the empathy dimension widened to human significance: dignity, vulnerability and power over the person, not only relationship value. The proposal’s five flat outcomes were not adopted: assisted grades are what the allocation crossed with the autonomy ladder already expresses. Thirteen dimensions; still no number.', es: 'El Fit Score se convirtió en el Fit Assessment — HWFA — y se reconstruyó en tres etapas. Primero el renombre: un instrumento que deliberadamente se niega a producir un número no debería llamarse Score, y retirar el acrónimo viejo disuelve además cualquier confusión residual entre el instrumento y el estándar. El rediseño corrige tres defectos que una revisión atrapó contra el código en ejecución: la dimensión de economía era circular — preguntaba qué alternativa gana y devolvía la respuesta como análisis — y ahora es un perfil de costos factual consultado solo en la etapa final; la enumerabilidad completa puntuaba hacia la IA probabilística cuando es la firma del territorio del software determinista, y el instrumento ahora tiene un cuarto resultado — automatización determinista — para trabajo por reglas con cola de excepciones delgada, porque un estándar de AI Employees cuyo instrumento sabe decir «no necesitás uno» es más difícil de descartar como hype; y el volumen jalaba hacia la automatización cuando la escala multiplica el daño, así que ahora amplifica la clase de riesgo. Las etapas encarnan el orden de HWF-20 — elegibilidad, luego riesgo, luego economía — abriendo con una dimensión nueva de materias reservadas cableada a HWF-23, y la dimensión de empatía ampliada a significancia humana: dignidad, vulnerabilidad y poder sobre la persona, no solo valor de la relación. Los cinco resultados planos de la propuesta no se adoptaron: los grados asistidos son lo que la asignación cruzada con la escalera de autonomía ya expresa. Trece dimensiones; sigue sin haber número.' },
      { en: 'HWF-27 gates change the way the playbook gates birth: a version is a record, not a proof, and every material change — model, tools, policies, knowledge, authority — is revalidated before it operates, at a depth set by the risk class. The author’s objection to the proposal shaped the clause: the test battery presupposes a stochastic system, and deterministic automation sits below the AI Employee category on the vocabulary ladder, so the obligations never touch it — while among AI Employees the dial is HWF-22’s class rather than all-or-nothing, with the adversarial and bias battery arriving from High upward. Team-level systemic risks are named, correlated failure above all: model monoculture is the one risk classical administration never had. ISO/IEC 42001 and 42005 and the NIST AI RMF are complemented, not recreated — the same subsidiarity the standard applies to labour law. Adds G-41 and both ISO standards to the sources.', es: 'HWF-27 compuerta el cambio como el playbook compuerta el nacimiento: una versión es un registro, no una prueba, y todo cambio material — modelo, herramientas, políticas, conocimiento, autoridad — se revalida antes de operar, a profundidad fijada por la clase de riesgo. La objeción del autor a la propuesta modeló la cláusula: la batería de pruebas presupone un sistema estocástico, y la automatización determinista está debajo de la categoría AI Employee en la escalera de vocabulario, así que las obligaciones nunca la tocan — mientras entre AI Employees el dial es la clase de HWF-22 y no el todo-o-nada, con la batería adversarial y de sesgo llegando de Alto hacia arriba. Los riesgos sistémicos de equipo quedan nombrados, la falla correlacionada ante todo: la monocultura de modelo es el único riesgo que la administración clásica nunca tuvo. ISO/IEC 42001 y 42005 y el NIST AI RMF se complementan, no se recrean — la misma subsidiariedad que el estándar aplica al derecho laboral. Agrega G-41 y ambos estándares ISO a las fuentes.' },
      { en: 'HWF-08 was extended from memory to the deployment’s whole data surface: inputs, outputs, tool results, memory and derived inferences, each with stated purpose and legal basis, minimisation, quality controls, sensitive-data handling, transfer and vendor-use rules including training, per-company isolation and verifiable deletion — deletion that cannot be evidenced is retention with extra steps. A derived inference is data manufactured about a person who never handed it over, governed as if collected. The clause also closes a loop the standard opened itself: its own audit requirements thicken an archive in which employees and customers appear, and the more conformant the deployment, the richer that archive grows — so the audit trail is governed with the same severity as the operation it audits, integrity protected, access controlled, purpose bound, because mining the safety apparatus to score employees or profile customers is a new purpose requiring its own basis. Adds G-40, aligns matrix principle 94, and adds GDPR Article 5 to the sources.', es: 'HWF-08 se extendió de la memoria a toda la superficie de datos del deployment: inputs, outputs, resultados de herramientas, memoria e inferencias derivadas, cada uno con finalidad y base legal declaradas, minimización, controles de calidad, manejo de datos sensibles, reglas de transferencia y de uso por el proveedor incluido el entrenamiento, aislamiento por empresa y eliminación verificable — una eliminación que no puede evidenciarse es retención con pasos extra. Una inferencia derivada es un dato fabricado sobre una persona que nunca lo entregó, gobernado como si se hubiera recolectado. La cláusula también cierra un circuito que el estándar abrió solo: sus propios requisitos de auditoría engordan un archivo donde aparecen empleados y clientes, y cuanto más conforme el deployment, más rico crece ese archivo — así que el registro de auditoría se gobierna con la misma severidad que la operación que audita, integridad protegida, acceso controlado, finalidad acotada, porque minar el aparato de seguridad para puntuar empleados o perfilar clientes es un propósito nuevo que exige su propia base. Agrega G-40, alinea el principio 94 de la matriz, y agrega el Artículo 5 del GDPR a las fuentes.' },
      { en: 'HWF-10 was rewritten from a purpose test into observable results. The old citable text prohibited simulating an interior state and its note tested what a behaviour was for — correct in diagnosis, weak in audit, because intent is not deposable and a standard whose other clauses demand operational evidence cannot keep one proved by mind-reading. The five prohibitions are now results: passing as human; claiming feelings, suffering or personal experience; signals reasonably capable of inducing a false belief; optimisation against recorded objectives for emotional dependency or exploited vulnerability; concealed artificial involvement at a material point. Two verifiable standards do the work the purpose test did: the reasonable-person effect standard, and the recorded optimisation objective — an artifact among HWF-06’s determinants, so the record convicts without confession. Disclosure gained a calendar: at the outset, renewed when the system assumes a material function, tracking EU AI Act Article 50 without claiming legal equivalence. The proposal’s “nonexistent feelings” rider was dropped to preserve the epistemic modesty adopted earlier: claiming feelings is claiming the unwarrantable, whether or not they exist. Courtesy, linguistic empathy and personalisation are now legal by citable text. G-30 carries the same two standards.', es: 'HWF-10 se reescribió de prueba de propósito a resultados observables. El texto citable anterior prohibía simular un estado interior y su nota probaba para qué existía una conducta — correcto en diagnóstico, débil en auditoría, porque la intención no es deponible y un estándar cuyas demás cláusulas exigen evidencia operacional no puede conservar una probada leyendo mentes. Las cinco prohibiciones ahora son resultados: hacerse pasar por humano; afirmar sentimientos, sufrimiento o experiencia personal; señales razonablemente capaces de inducir creencia falsa; optimización contra objetivos registrados de dependencia emocional o vulnerabilidad explotada; intervención artificial ocultada en un punto material. Dos estándares verificables hacen el trabajo que hacía la prueba de propósito: el estándar de efecto de la persona razonable, y el objetivo de optimización registrado — un artefacto entre los determinantes de HWF-06, así que el registro condena sin confesión. La divulgación ganó calendario: al inicio, renovada cuando el sistema asume una función material, siguiendo el Artículo 50 del EU AI Act sin afirmar equivalencia jurídica. El rider de «sentimientos inexistentes» de la propuesta se descartó para preservar la modestia epistémica adoptada antes: afirmar sentimientos es afirmar lo ingarantizable, existan o no. La cortesía, la empatía lingüística y la personalización ahora son legales por texto citable. G-30 carga los mismos dos estándares.' },
      { en: 'HWF-02 was extended in place rather than joined by a new clause, because both additions concern its own subject — the terminus of accountability. One is primary, not exclusive: exactly one answers who answers for the resource, and was never meant to extinguish the distinct obligations of system owner, data controller, security and compliance owners, technology vendor or legally responsible directors — a reading that would have been a gift to every party hoping to hide behind the operational owner, and that HWF-26 had already half-closed from the blame side by routing failures to their determinants. And a governance body qualifies as terminus only with an identified chair, stated decision rules and emergency capacity, because a body that needs a meeting to act cannot hold the power to suspend that HWF-26 requires — without those it is not an owner but a diffusion mechanism. G-04, WRM rule 2 and matrix principle 7 carry the same qualification. Clause and term counts unchanged.', es: 'HWF-02 se extendió en el lugar en vez de sumarle una cláusula nueva, porque ambas adiciones tratan su propio tema — el terminus de la accountability. Uno es primario, no exclusivo: exactamente uno responde quién responde por el recurso, y nunca pretendió extinguir las obligaciones distintas del system owner, el controller de datos, los dueños de seguridad y compliance, el proveedor tecnológico o los directores legalmente responsables — una lectura que habría sido un regalo para toda parte que quisiera esconderse detrás del owner operativo, y que HWF-26 ya había medio cerrado desde el lado de la culpa al rutear las fallas a sus determinantes. Y un cuerpo de gobierno califica como terminus solo con presidente identificado, reglas de decisión declaradas y capacidad de emergencia, porque un cuerpo que necesita una reunión para actuar no puede sostener el poder de suspender que HWF-26 exige — sin eso no es un owner sino un mecanismo de difusión. G-04, la regla 2 del WRM y el principio 7 de la matriz cargan la misma precisión. Conteos de cláusulas y términos sin cambio.' },
      { en: 'HWF-26 turns accountable ownership from a name in a field into a resourced capability: competence, effective authority, time and capacity for the span, direct access to evidence, independence from the pressures that own the outcome, the power to suspend, and training on limitations and automation bias. The suspension mechanism is exercised on a stated cadence — a kill switch that has never been pulled is decoration, and the first real pull must not be the first pull ever. The clause also prohibits the moral crumple zone, after Elish: blame follows the determinants of HWF-06, not the proximity, so the supervising human answers for what they controlled and upstream failures land upstream — which completes HWF-02 from the other side, because consequence without control is scapegoating, and protects the owner as much as the truth. Adds G-39, Elish (2019) as a source, and a tested-cadence kill switch to the Hybrid Workforce Manager’s guarantees.', es: 'HWF-26 convierte la accountable ownership de nombre en un campo a capacidad dotada de recursos: competencia, autoridad efectiva, tiempo y capacidad para el alcance, acceso directo a la evidencia, independencia de las presiones dueñas del resultado, poder de suspender, y entrenamiento en limitaciones y sesgo de automatización. El mecanismo de suspensión se ejercita con cadencia declarada — un kill switch que nunca se ha jalado es decoración, y la primera jalada real no puede ser la primera jalada. La cláusula también prohíbe la zona de absorción moral, según Elish: la culpa sigue a los determinantes de HWF-06, no a la proximidad, así que el humano que supervisa responde por lo que controló y las fallas de aguas arriba aterrizan aguas arriba — lo que completa HWF-02 desde el otro lado, porque consecuencia sin control es chivo expiatorio, y protege al dueño tanto como a la verdad. Agrega G-39, Elish (2019) como fuente, y un kill switch con cadencia probada a las garantías del Gerente de Fuerza Laboral Híbrida.' },
      { en: 'HWF-25 gives the affected person standing: seven rights against the deployment — disclosure of artificial involvement, the responsible organisation, human review with authority to change the outcome, data correction, contest, an actionable explanation of determinants, and redress. The explanation is operational evidence in HWF-06’s exact vocabulary and never a reasoning transcript, which handed to an affected person is an unfalsifiable story wearing the authority of an explanation — operational evidence is disputable, and nobody can contest a vibe. At the author’s direction the release runs through human judgement: privileged or confidential material may be withheld, because published fraud thresholds are defeated fraud thresholds and “explain yourself” is a prompt-extraction surface; the counter-lock is HWF-18’s discipline faced outward — every withholding recorded with its reason, and confidentiality narrows an explanation but never cancels it. Interoperates with GDPR Articles 15 and 22(3) and EU AI Act Article 86. Adds G-38 and Article 86 to the sources.', es: 'HWF-25 le da voz a la persona afectada: siete derechos frente al deployment — divulgación de la intervención artificial, la organización responsable, revisión humana con autoridad para cambiar el resultado, corrección de datos, impugnación, una explicación accionable de los determinantes, y reparación. La explicación es evidencia operacional en el vocabulario exacto de HWF-06 y nunca una transcripción de razonamiento, que entregada a una persona afectada es una historia infalsificable vestida con la autoridad de una explicación — la evidencia operacional es disputable, y nadie puede impugnar una vibra. Por dirección del autor la entrega corre por criterio humano: el material privilegiado o confidencial puede retenerse, porque los umbrales de fraude publicados son umbrales de fraude derrotados y «explícate» es una superficie de extracción de prompt; el contra-candado es la disciplina de HWF-18 volteada hacia afuera — toda retención registrada con su razón, y la confidencialidad estrecha una explicación pero nunca la cancela. Interopera con los Artículos 15 y 22(3) del GDPR y el Artículo 86 del EU AI Act. Agrega G-38 y el Artículo 86 a las fuentes.' },
      { en: 'HWF-24 makes a recorded human impact assessment a precondition of any material transformation of a post, in either direction. Eight dimensions — who is affected; work, autonomy and surveillance; deskilling; exception load; discrimination and accessibility; displacement and headcount; training and reassignment; customers and third parties — with affected workers and their representatives informed and consulted before the transformation. The gap was visible in the playbook itself, where people appeared once, as released capacity, in step ten; the assessment now runs before step one, and step ten executes against its training and reassignment plan. Consultation is not consent and no veto is granted; the clause is a floor interoperating with EU AI Act Article 26 without claiming legal equivalence. No favourable conclusion is required — an assessment obliged to bless the transition would be theatre. Adds G-37 and Article 26 to the sources.', es: 'HWF-24 vuelve una evaluación de impacto humano registrada precondición de toda transformación material de un puesto, en cualquier dirección. Ocho dimensiones — a quiénes afecta; trabajo, autonomía y vigilancia; deskilling; carga de excepciones; discriminación y accesibilidad; desplazamiento y reducción de personal; capacitación y reasignación; clientes y terceros — con los trabajadores afectados y sus representantes informados y consultados antes de la transformación. El hueco era visible en el propio playbook, donde las personas aparecían una vez, como capacidad liberada, en el paso diez; la evaluación ahora corre antes del paso uno, y el paso diez se ejecuta contra su plan de capacitación y reasignación. La consulta no es consentimiento y no se otorga veto; la cláusula es piso e interopera con el Artículo 26 del EU AI Act sin afirmar equivalencia jurídica. No se exige conclusión favorable — una evaluación obligada a bendecir la transición sería teatro. Agrega G-37 y el Artículo 26 a las fuentes.' },
      { en: 'HWF-23 reserves certain decisions to humans by subject matter: material effects on employment, health and safety, credit and essential services, legal rights, use of force, and vulnerable people. It exists because HWF-22 classifies by judgement and judgement can be motivated — the list is the floor no assessment can lower, and a reserved decision is Critical by definition. Artificial participation remains allowed: analysis, drafting, recommendation. The decision may not be delegated, and the clause defines what deciding means — an approval by a human who cannot restate the case and decide otherwise is a signature, not a decision — because human-in-the-loop degenerates into approval throughput by default. Interoperates with GDPR Article 22 and the EU AI Act’s oversight requirements without claiming legal equivalence. Adds G-36 and GDPR Article 22 to the sources.', es: 'HWF-23 reserva ciertas decisiones a humanos por materia: efectos materiales sobre empleo, salud y seguridad, crédito y servicios esenciales, derechos legales, uso de la fuerza y personas vulnerables. Existe porque HWF-22 clasifica por juicio y el juicio puede estar motivado — la lista es el piso que ninguna evaluación puede bajar, y una decisión reservada es Crítica por definición. La participación artificial sigue permitida: análisis, redacción, recomendación. La decisión no puede delegarse, y la cláusula define qué significa decidir — una aprobación de un humano que no puede reformular el caso y decidir distinto es una firma, no una decisión — porque el human-in-the-loop degenera por defecto en ritmo de aprobación. Interopera con el Artículo 22 del GDPR y los requisitos de supervisión del EU AI Act sin afirmar equivalencia jurídica. Agrega G-36 y el Artículo 22 del GDPR a las fuentes.' },
      { en: 'HWF-22 defines the five-tier risk classification the document previously used without defining: Prohibited, Critical, High, Moderate, Low. HWF-05 spoke of high-risk actions and HWF-21 required a risk class in every conformance declaration, and neither term resolved anywhere. The class is judged on inherent risk across seven factors — rights, scale, reversibility, vulnerable people, data sensitivity, adversarial exposure, concentration of power — never on cost of error alone, and controls lower residual risk but never the class, so a guardrail cannot buy a better tier. Critical always terminates in a final human decision; Prohibited cannot be made conformant by any control and is a precondition of the HWFS rather than an output of it. The tiers interoperate with risk-based regimes such as the EU AI Act without claiming legal equivalence. Adds G-35, the classification table, and the EU AI Act to the sources.', es: 'HWF-22 define la clasificación de riesgo de cinco niveles que el documento usaba sin definir: Prohibido, Crítico, Alto, Moderado, Bajo. HWF-05 hablaba de acciones de alto riesgo y HWF-21 exigía una clase de riesgo en toda declaración de conformidad, y ninguno de los dos términos resolvía en ninguna parte. La clase se juzga sobre el riesgo inherente a través de siete factores — derechos, escala, reversibilidad, personas vulnerables, sensibilidad de datos, exposición adversarial, concentración de poder — nunca sobre el costo del error a solas, y los controles bajan el riesgo residual pero nunca la clase, así que un guardrail no puede comprar un mejor nivel. Crítico termina siempre en una decisión humana final; Prohibido no puede volverse conforme mediante ningún control y es una precondición del HWFS, no un output suyo. Los niveles interoperan con regímenes basados en riesgo como el EU AI Act sin afirmar equivalencia jurídica. Agrega G-35, la tabla de clasificación, y el EU AI Act a las fuentes.' },
      { en: 'The nine-property test became conjunctive. The caveat said a system “missing several” properties may still be an agent, which implied one or two absences were tolerable — indefensible for defining properties, all nine of which the clauses already require individually, and an open invitation to seven-of-nine marketing. Qualification now requires all nine, with presence binary and depth graded by the maturity model. The proposal’s second half — tying qualification to satisfying the clauses as well — was rejected for vacuity: if violating a clause removed the category, no deployment could ever violate the standard, because violators would exit it instead of breaching it. A deployment in breach is a non-conformant AI Employee, not a non-AI-Employee.', es: 'El test de nueve propiedades se volvió conjuntivo. La advertencia decía que un sistema al que le «faltan varias» propiedades puede seguir siendo un agente, lo que implicaba que una o dos ausencias eran tolerables — indefendible para propiedades definitorias, cuyas nueve las cláusulas ya exigen individualmente, y una invitación abierta al marketing de siete-de-nueve. La calificación ahora exige las nueve, con presencia binaria y profundidad graduada por el modelo de madurez. La segunda mitad de la propuesta — atar la calificación también al cumplimiento de las cláusulas — se rechazó por vacuidad: si violar una cláusula quitara la categoría, ningún deployment podría jamás violar el estándar, porque los infractores saldrían de él en vez de incumplirlo. Un deployment en falta es un AI Employee no conforme, no un no-AI-Employee.' },
      { en: 'HWF-21 defines the unit of conformance: a deployment, never a product, platform or organisation in the abstract. Every claim publishes nine fields — organisation and deployment, role and contract version, accountable owner, risk class, clauses assessed, assessment period, evidence, known limitations, expiry — so that self-declaration stays falsifiable instead of decaying into a marketing phrase. A vendor may state that its platform enables conformant deployments and may never state that the platform conforms; the first platform bound is the author’s own. The declaration template names the standard in full: “HWFS conformance” was considered and rejected because HWFS already names the Hybrid Workforce Fit Score, and a conformance claim must not be confusable with the allocation instrument. Adds G-34 and the nine-field declaration template.', es: 'HWF-21 define la unidad de conformidad: un deployment, nunca un producto, plataforma ni organización en abstracto. Toda declaración publica nueve campos — organización y deployment, rol y versión de contrato, accountable owner, clase de riesgo, cláusulas evaluadas, periodo de evaluación, evidencia, limitaciones conocidas, expiración — para que la autodeclaración siga siendo falsificable en vez de degenerar en frase de marketing. Un proveedor puede declarar que su plataforma habilita deployments conformes y nunca que la plataforma conforma; la primera plataforma atada es la del propio autor. La plantilla de declaración nombra el estándar completo: se consideró y rechazó «HWFS conformance» porque HWFS ya nombra el Hybrid Workforce Fit Score, y una declaración de conformidad no debe confundirse con el instrumento de asignación. Agrega G-34 y la plantilla de declaración de nueve campos.' },
      { en: 'A proposal to split the document into five separately governed pieces — core standard, conformance specification, WRM framework, HWFS instrument, playbooks — and to rename it the Hybrid Workforce Governance Standard was declined. The editorial-regime separation it asked for already exists as layers under one cover, and is now stated explicitly in the reading section; five documents would multiply versions, citations and cross-reference drift for a one-editor project while fragmenting the single machine-readable file the standard is delivered as. The rename was declined on scope and position: clauses concentrate on AI Employees by subsidiarity — the human side of the workforce is already governed by labour law and existing HR standards — while the doctrine, the matrix, the transitions and HWF-20 govern the whole hybrid workforce; and “governance” would both narrow the document and shelve it against general AI-governance frameworks, the exact competition it does not seek. Extraction into separate pieces remains available to a future version and its Board if an ecosystem of auditors ever requires it.', es: 'Se declinó una propuesta de dividir el documento en cinco piezas gobernadas por separado — estándar central, especificación de conformidad, marco WRM, instrumento HWFS, playbooks — y de renombrarlo Hybrid Workforce Governance Standard. La separación de régimen editorial que pedía ya existe como capas bajo una sola portada, y ahora queda declarada explícitamente en la sección de lectura; cinco documentos multiplicarían versiones, citas y deriva de referencias cruzadas para un proyecto de un solo editor, fragmentando además el único archivo legible por máquinas en que el estándar se entrega. El renombre se declinó por alcance y posicionamiento: las cláusulas se concentran en AI Employees por subsidiariedad — el lado humano de la fuerza laboral ya está gobernado por el derecho laboral y los estándares de RR. HH. existentes — mientras la doctrina, la matriz, las transiciones y HWF-20 gobiernan la fuerza laboral híbrida completa; y «governance» estrecharía el documento y lo pondría en el estante de los marcos generales de gobernanza de IA, exactamente la competencia que no busca. La extracción en piezas separadas queda disponible para una versión futura y su Board si algún día un ecosistema de auditores la exige.' },
      { en: 'HWF-20 declares the ethical hierarchy and takes precedence over every other clause: people are ends, software is a means, and optimisation of cost, speed or capacity never overrides human rights, dignity, safety, meaningful human agency, accessibility or applicable labour protections — resource neutrality begins only after those constraints are satisfied. Adopted nearly as proposed, with a supremacy sentence added so that its position in the list is not read as its rank. It does not promise that displacement will not happen; it draws the line between displacement and abuse, naming the hierarchy the anti-KPI and the HWFS hard gates already obeyed. Adds G-33, bounds the Hybrid Workforce Manager’s neutrality mandate, and adds the OECD AI Principles to the sources.', es: 'HWF-20 declara la jerarquía ética y tiene precedencia sobre toda otra cláusula: las personas son fines, el software es un medio, y la optimización de costo, velocidad o capacidad nunca pasa por encima de los derechos humanos, la dignidad, la seguridad, la agencia humana significativa, la accesibilidad ni las protecciones laborales aplicables — la neutralidad de recurso comienza solo después de satisfechas esas restricciones. Adoptada casi como fue propuesta, con una oración de supremacía agregada para que su posición en la lista no se lea como su rango. No promete que el desplazamiento no ocurrirá; traza la línea entre desplazamiento y abuso, nombrando la jerarquía que el anti-KPI y las compuertas duras del HWFS ya obedecían. Agrega G-33, acota el mandato de neutralidad del Gerente de Fuerza Laboral Híbrida, y agrega los Principios de IA de la OCDE a las fuentes.' },
      { en: 'The WRM premise and the HWF-01 note now answer the Taylorism objection directly. A proposed rewrite would have replaced “the post exists before its occupant” with an authority-gating sentence plus co-evolution reserved for human roles. It was not adopted: the gating sentence restates HWF-03 and WRM rules 3–4, restricting co-evolution to human roles contradicts HWF-17, and deleting the premise would dissolve the allocation framework the HWFS depends on. What was adopted is the distinction the objection actually needed: the declaration governs the order of birth, not the rest of the life. Job crafting is legitimate and expected — Taylor fixed the person to the box; this standard versions the box — and every reshaping must be declared, because in a hybrid organisation the declared post is the interface: a human colleague can read an undeclared role from the corridor, an artificial one can only read the graph. No clause text changed.', es: 'La premisa del WRM y la nota de HWF-01 ahora responden directamente la objeción de taylorismo. Una reescritura propuesta habría reemplazado «el puesto existe antes que su ocupante» por una oración de compuerta de autoridad más co-evolución reservada a los roles humanos. No se adoptó: la compuerta reformula HWF-03 y las reglas 3–4 del WRM, restringir la co-evolución a roles humanos contradice HWF-17, y borrar la premisa disolvería el marco de asignación del que depende el HWFS. Se adoptó la distinción que la objeción realmente necesitaba: la declaración gobierna el orden del nacimiento, no el resto de la vida. El job crafting es legítimo y esperado — Taylor fijaba a la persona a la caja; este estándar versiona la caja — y toda remodelación debe declararse, porque en una organización híbrida el puesto declarado es la interfaz: un colega humano puede leer un rol no declarado desde el pasillo, uno artificial solo puede leer el grafo. Ningún texto de cláusula cambió.' },
      { en: 'HWF-10 and HWF-11 were rewritten for epistemic modesty. HWF-10’s citable text ended by asserting that the system “does not have” the interior states it simulates — a metaphysical thesis presented as technical fact. The rider was removed: “simulate” already carries the falsity, and the prohibition now survives any resolution of the philosophy of mind, because performing unverifiable interior states to influence a person is deception regardless. HWF-11 now states the standard’s position explicitly: it recognises no personhood, employment relationship, consciousness or moral status in an artificial system and does not claim to settle what future systems may warrant — non-recognition in the posture of corporate law, not denial. Supporting text moved to the same footing: the status line rather than the ontological line, no recognised interests rather than no interests, analogies rejected as operationally empty rather than metaphysically false.', es: 'HWF-10 y HWF-11 se reescribieron por modestia epistémica. El texto citable de HWF-10 cerraba afirmando que el sistema «no tiene» los estados interiores que simula — una tesis metafísica presentada como hecho técnico. El remate se eliminó: «simular» ya carga la falsedad, y la prohibición ahora sobrevive a cualquier resolución de la filosofía de la mente, porque actuar estados interiores inverificables para influir en una persona es engaño de todos modos. HWF-11 ahora declara explícitamente la posición del estándar: no reconoce personería, relación laboral, conciencia ni estatus moral en un sistema artificial y no pretende resolver lo que sistemas futuros puedan ameritar — no-reconocimiento en la postura del derecho societario, no negación. El texto de apoyo pasó al mismo pie: la línea de estatus en vez de la línea ontológica, sin intereses reconocidos en vez de sin intereses, analogías rechazadas por vacías operativamente y no por falsas metafísicamente.' },
      { en: 'The thesis line and the vocabulary ladder were corrected for consistency with the standard’s own accountability architecture. The English edition read “an AI Employee is accountable for a role” and the ladder promised “ownership of a role”, while HWF-02’s note defines accountability as requiring the capacity to bear a legal, financial or reputational consequence and the accountable owner is human by definition. The thesis now ends where every chain in the standard ends — an AI Employee holds a role; a human answers for it — the ladder promises stewardship rather than ownership, and the invariant is stated as a formula: the AI executes, the organisation answers, a human governs. No clause text changed.', es: 'La línea de tesis y la escalera de vocabulario se corrigieron por consistencia con la propia arquitectura de accountability del estándar. La edición en inglés decía «an AI Employee is accountable for a role» y la escalera prometía «propiedad de un rol», mientras la nota de HWF-02 define la accountability como la capacidad de cargar una consecuencia legal, financiera o reputacional y el accountable owner es humano por definición. La tesis ahora termina donde termina toda cadena del estándar — un AI Employee ocupa un rol; un humano responde por él — la escalera promete custodia en vez de propiedad, y el invariante queda enunciado como fórmula: la IA ejecuta, la organización responde, un humano gobierna. Ningún texto de cláusula cambió.' },
      { en: 'HWF-19 forbids a post from outliving its justification: at a stated cadence the accountable owner re-justifies its existence against current strategy, as a question prior to and separate from performance, and continuation is never the default. The clause replaces a pruning mechanism that artificial occupants lack — payroll and attrition remove pointless human posts, and a resource that costs little and never resigns persists by default, accumulating organisational debt in its most dangerous form: digital zombies holding access for work nobody needs. The proposed twelve-month period moved to the note as guidance, because the standard fixes mechanisms rather than calendars. Adds G-32 and extends WRM rule 1 and matrix principle 101.', es: 'HWF-19 prohíbe que un puesto sobreviva a su justificación: con cadencia declarada el accountable owner re-justifica su existencia frente a la estrategia vigente, como pregunta previa y separada del desempeño, y la continuidad nunca es el default. La cláusula reemplaza un mecanismo de poda que los ocupantes artificiales no tienen — payroll y attrition eliminan los puestos humanos sin sentido, y un recurso que cuesta poco y no renuncia jamás persiste por defecto, acumulando deuda organizacional en su forma más peligrosa: zombis digitales con accesos para trabajo que nadie necesita. El periodo de doce meses propuesto pasó a la nota como orientación, porque el estándar fija mecanismos y no calendarios. Agrega G-32 y extiende la regla 1 del WRM y el principio 101 de la matriz.' },
      { en: 'HWF-18 makes context provisioning deliberate in both directions. The restriction categories existed from the first draft, but every stated reason for them was informational risk, so nothing stopped a manager from granting all non-sensitive context even where it would degrade the resource’s judgement through anchoring, confirmation bias or overload. The proposal behind it asked for a new WRM domain of opacity; it entered as a clause instead, because opacity is a technique inside existing domains rather than a management function. The clause makes the record mandatory and assigns responsibility for decisions degraded by withheld context to whoever withheld it, because undocumented opacity is an accountability-laundering instrument. Adds G-31 and extends G-06, matrix principle 57 and WRM rule 6.', es: 'HWF-18 hace que el aprovisionamiento de contexto sea deliberado en ambas direcciones. Las categorías de restricción existían desde el primer borrador, pero toda razón declarada era el riesgo informacional, así que nada impedía que un manager concediera todo el contexto no sensible incluso donde degradaría el criterio del recurso por anclaje, sesgo de confirmación o sobrecarga. La propuesta que la originó pedía un nuevo dominio de opacidad en el WRM; entró como cláusula, porque la opacidad es una técnica dentro de dominios existentes y no una función de administración. La cláusula vuelve obligatorio el registro y asigna la responsabilidad por decisiones degradadas por contexto retenido a quien lo retuvo, porque la opacidad sin documentar es un instrumento de lavado de accountability. Agrega G-31 y extiende G-06, el principio 57 de la matriz y la regla 6 del WRM.' },
      { en: 'HWF-10 now prohibits simulating an interior state the system does not have, alongside deceiving anyone about its nature as software. Disclosure alone left a gap: a system could announce itself as software and still perform hesitation and warmth designed to lower the reader’s guard. The clause targets purpose rather than surface, so fluency and courtesy remain competence while injected latency, verbal hesitation and claims of feeling do not. The proposal behind it asked for communication to be functionally distinguishable from human interaction, which would have required AI Employees to write badly and would have been unauditable.', es: 'HWF-10 ahora prohíbe simular un estado interior que el sistema no tiene, además de engañar sobre su naturaleza de software. La divulgación sola dejaba un hueco: un sistema podía anunciarse como software y aun así actuar vacilación y calidez diseñadas para bajarle la guardia a quien lee. La cláusula apunta al propósito y no a la superficie, así que la fluidez y la cortesía siguen siendo competencia mientras la latencia inyectada, las muletillas de vacilación y las declaraciones de sentimiento no lo son. La propuesta que la originó pedía que la comunicación fuera funcionalmente distinguible de una interacción humana, lo que habría obligado a los AI Employees a escribir mal y habría sido inauditable.' },
      { en: 'HWF-06 now requires an audit to reconstruct the determinants of a decision — policy, knowledge, tool results, authority and versions in force — and not only its outcome. A what-only audit leaves a wrong policy, stale knowledge, a bad tool result, a model error and a misassigned role looking identical, and those five need different remedies. The clause states in its citable text that a model’s account of its own reasoning supports the reconstruction without substituting for it, because stated reasoning is not reliable evidence of cause and a standard that accepted it would license confidently wrong postmortems.', es: 'HWF-06 ahora exige que la auditoría reconstruya los determinantes de una decisión — política, conocimiento, resultados de herramientas, autoridad y versiones vigentes — y no solo su resultado. Una auditoría de solo-qué deja idénticos a una política equivocada, un conocimiento envejecido, un mal resultado de herramienta, un error de modelo y un rol mal asignado, y esos cinco necesitan remedios distintos. La cláusula dice en su texto citable que el relato del modelo sobre su propio razonamiento apoya la reconstrucción sin sustituirla, porque el razonamiento declarado no es evidencia confiable de causa y un estándar que lo aceptara habilitaría postmortems confiados y equivocados.' },
      { en: 'HWF-17 requires a role contract to be revisable, to be reviewed on a stated cadence, and to have divergence between measured outcomes and stated mission reported upward by the resource itself. It is framed as a finding rather than a request: an AI Employee has no interests to advance, and a system able to argue for its own expanded authority is a privilege-escalation path dressed as an HR feature. The decision stays with the accountable owner and never with an artificial supervisor.', es: 'HWF-17 exige que un contrato de rol sea revisable, se revise con cadencia declarada, y que la divergencia entre outcomes medidos y misión declarada la reporte hacia arriba el propio recurso. Está formulada como hallazgo y no como solicitud: un AI Employee no tiene intereses que defender, y un sistema capaz de argumentar a favor de su propia autoridad ampliada es un camino de escalamiento de privilegios vestido de función de RR. HH. La decisión queda en el accountable owner y nunca en un supervisor artificial.' },
      { en: 'HWF-02 separates supervision from accountability. An AI Employee may supervise another; accountability terminates in an identified human or governance body no matter how deep the chain. HWF-16 was added alongside it, requiring that chain to be traversable, observable, and interruptible without passing through itself. Before publication these read as a single clause requiring a direct human manager, which would have made a deep artificial hierarchy non-conformant by wording rather than by intent.', es: 'HWF-02 separa supervisión de accountability. Un AI Employee puede supervisar a otro; la accountability termina en un humano o cuerpo de gobierno identificado por profunda que sea la cadena. HWF-16 se agregó junto con ella, exigiendo que esa cadena sea recorrible, observable e interrumpible sin pasar por sí misma. Antes de publicar, ambas eran una sola cláusula que exigía manager humano directo, lo que habría vuelto no conforme a una jerarquía artificial profunda por redacción y no por intención.' },
    ],
  },
];

export const VERSIONING_POLICY: T = {
  en: 'Clause text changes require a version bump and a Board vote. Notes, examples and commentary may be corrected between versions without amending the standard. Every published version stays at its own permanent address so that a citation made today still resolves in five years.',
  es: 'Cambiar el texto de una cláusula exige subir de versión y una votación del Board. Notas, ejemplos y comentario pueden corregirse entre versiones sin enmendar el estándar. Toda versión publicada permanece en su propia dirección permanente para que una cita hecha hoy siga resolviendo en cinco años.',
};
